import type { Environment, RicosTheme } from './../ricos-types/index.js';
import { deepMerge } from './../_shared/deep-merge.js';

import {
  HEADING_FONT_SIZES,
  PARAGRAPH_FONT_SIZE,
  ACTION_COLOR_DEFAULT,
  BG_COLOR_DEFAULT,
  TEXT_COLOR_DEFAULT,
} from './theme-constants.js';

type ResolveThemeOptions = {
  theme?: RicosTheme;
  environment?: Environment;
  isMobile?: boolean;
};

/**
 * Single theme resolution function.
 *
 * Merge order: baseDefaults <- envPreset <- userTheme <- priorityOverrides
 *
 * - baseDefaults: device-specific defaults (desktop/mobile font sizes, palette)
 * - envPreset: environment-specific preset (wix/liveSite/native)
 * - userTheme: user-provided theme overrides
 * - priorityOverrides: forced overrides that cannot be changed by the user (wix-only)
 */
export const resolveTheme = ({
  theme = {},
  environment,
  isMobile = false,
}: ResolveThemeOptions): RicosTheme => {
  const { useWixStyles, useNativeStyles, ...userTheme } = theme;

  // 1. Determine environment
  const isWix = useWixStyles || environment === 'businessManager' || environment === 'wixel';
  const envPreset = useNativeStyles ? nativePreset : isWix ? wixPreset : liveSitePreset;

  // 2. Pick device-specific base defaults
  const baseDefaults = isMobile ? THEME_DEFAULTS.mobile : THEME_DEFAULTS.desktop;

  // 3. Merge in clear, documented order:
  //    base defaults <- environment preset <- user overrides <- priority overrides
  return deepMerge<RicosTheme>(
    {},
    baseDefaults,
    envPreset,
    userTheme,
    isWix ? wixPriorityOverrides : {}
  );
};

