import type { TextStyle as TextStyleRichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { CustomTextualStyle } from './../../ricos-types/index.js';

type TextStyleWithoutAlignment = Omit<TextStyleRichContent, 'textAlignment'>;

export class RicosTextStyle {
  textStyle: TextStyleWithoutAlignment;

  private constructor(textStyle: TextStyleWithoutAlignment) {
    this.textStyle = Object.fromEntries(Object.entries(textStyle).filter(([, value]) => !!value));
  }

  static of(textStyle: TextStyleWithoutAlignment): RicosTextStyle {
    return new RicosTextStyle(textStyle || {});
  }

  getTextStyle = (): TextStyleWithoutAlignment => this.textStyle;

  static fromCustomStyle = (customStyle: CustomTextualStyle): RicosTextStyle => {
    const { lineHeight } = customStyle;
    const textStyle = { lineHeight } as TextStyleRichContent;
    return RicosTextStyle.of(textStyle);
  };

  toCustomStyle = (): CustomTextualStyle => {
    return { lineHeight: this.textStyle.lineHeight };
  };

  overrideWith = (textStyle: TextStyleWithoutAlignment): RicosTextStyle => {
    return RicosTextStyle.of({ ...this.textStyle, ...textStyle });
  };
}
