import classNames from 'classnames';

import type { Environment } from './../ricos-types/index.js';

import styles from './statics/styles/style-presets-scss.js';

export const getStyles = (environment: Environment, isMobile: boolean): string | null =>
  classNames({
    [styles.liveSite]: environment === 'liveSite',
    [styles.businessManager]: environment === 'businessManager',
    [styles.wixel]: environment === 'wixel',
    [styles.mobile]: isMobile,
  });
